    public static FfiConverterTypeLinkKind INSTANCE = new FfiConverterTypeLinkKind();

    public override LinkKind Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1: return LinkKind.Auth;
            case 2: return LinkKind.Handoff;
            case 3: return LinkKind.Unknown;
            default: throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeLinkKind.Read()", value));
        }
    }

    public override int AllocationSize(LinkKind value) {
        return 4;
    }

    public override void Write(LinkKind value, BigEndianStream stream) {
        switch (value) {
            case LinkKind.Auth: stream.WriteInt(1); break;
            case LinkKind.Handoff: stream.WriteInt(2); break;
            case LinkKind.Unknown: stream.WriteInt(3); break;
            default: throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeLinkKind.Write()", value));
        }
    }
}







